/**
 * Memory API Handler
 *
 * Framework-agnostic helpers for memory CRUD endpoints.
 * Apps can wrap these in their HTTP framework (Next.js, Express, etc.)
 */

import type {
  MemoryEntry,
  MemoryStore,
  VectorStore,
  WorkingMemoryManager,
} from './types';
import { consolidateMemories, type ConsolidationConfig, type ConsolidationResult } from './consolidation';
import { pruneMemories, type DecayConfig, type PruneResult } from './decay';
import { calculateMemoryStats, type MemoryStats } from './analytics';

export interface MemoryAPIConfig {
  workingMemory: WorkingMemoryManager;
  memoryStore: MemoryStore;
  vectorStore?: VectorStore;
  embeddings?: import('./types').EmbeddingsAdapter;
}

export interface HealthStatus {
  status: 'healthy' | 'degraded';
  memoryStore: boolean;
  vectorStore: boolean;
}

/**
 * Create a memory API handler with all CRUD operations.
 */
export function createMemoryAPIHandler(config: MemoryAPIConfig) {
  const { workingMemory, memoryStore, vectorStore, embeddings } = config;

  return {
    /** List memories with optional filtering */
    async list(
      userId: string,
      filters?: {
        category?: MemoryEntry['category'];
        memoryType?: MemoryEntry['memoryType'];
        persistenceLevel?: MemoryEntry['persistenceLevel'];
        limit?: number;
      },
    ): Promise<MemoryEntry[]> {
      let memories = await memoryStore.listByUser(userId, {
        category: filters?.category,
        limit: filters?.limit,
      });

      // Apply additional filters
      if (filters?.memoryType) {
        memories = memories.filter(m => m.memoryType === filters.memoryType);
      }
      if (filters?.persistenceLevel) {
        memories = memories.filter(m => m.persistenceLevel === filters.persistenceLevel);
      }

      // Exclude superseded
      memories = memories.filter(m => !m.supersededBy);

      return memories;
    },

    /** Get a single memory by ID */
    async get(id: string): Promise<MemoryEntry | null> {
      return memoryStore.get(id);
    },

    /** Update a memory entry */
    async update(id: string, updates: Partial<MemoryEntry>): Promise<MemoryEntry | null> {
      const existing = await memoryStore.get(id);
      if (!existing) return null;

      const updated: MemoryEntry = {
        ...existing,
        ...updates,
        id: existing.id, // Prevent ID override
        userId: existing.userId, // Prevent userId override
        version: (existing.version ?? 1) + 1,
      };

      await memoryStore.save(updated);

      // Re-embed if content changed
      if (updates.content && updates.content !== existing.content && embeddings && vectorStore) {
        try {
          const embedding = await embeddings.embed(updated.content);
          updated.embedding = embedding;
          await memoryStore.save(updated);
          await vectorStore.upsert([{
            id: updated.id,
            vector: embedding,
            metadata: {
              userId: updated.userId,
              category: updated.category,
              content: updated.content,
            },
          }]);
        } catch {
          // Continue without re-embedding
        }
      }

      return updated;
    },

    /** Delete a memory */
    async delete(id: string): Promise<void> {
      await memoryStore.delete(id);
      if (vectorStore) {
        try {
          await vectorStore.delete([id]);
        } catch {
          // Continue
        }
      }
    },

    /** Export all memories for a user */
    async export(userId: string): Promise<MemoryEntry[]> {
      return memoryStore.listByUser(userId);
    },

    /** Import memories for a user with deduplication */
    async import(userId: string, entries: MemoryEntry[]): Promise<number> {
      let imported = 0;
      const existing = await memoryStore.listByUser(userId);
      const existingContents = new Set(existing.map(e => e.content.toLowerCase()));

      for (const entry of entries) {
        // Skip duplicates
        if (existingContents.has(entry.content.toLowerCase())) continue;

        // Override userId to prevent cross-user injection
        const safe: MemoryEntry = {
          ...entry,
          userId,
          lastAccessedAt: Date.now(),
        };

        await memoryStore.save(safe);

        // Generate embedding
        if (embeddings && vectorStore) {
          try {
            const embedding = await embeddings.embed(safe.content);
            safe.embedding = embedding;
            await memoryStore.save(safe);
            await vectorStore.upsert([{
              id: safe.id,
              vector: embedding,
              metadata: { userId, category: safe.category, content: safe.content },
            }]);
          } catch {
            // Continue without embedding
          }
        }

        imported++;
      }

      return imported;
    },

    /** Get memory statistics */
    async stats(userId: string): Promise<MemoryStats> {
      const memories = await memoryStore.listByUser(userId);
      return calculateMemoryStats(memories);
    },

    /** Health check */
    async health(): Promise<HealthStatus> {
      let memoryOk = true;
      let vectorOk = true;

      try {
        await memoryStore.listByUser('__health_check__', { limit: 1 });
      } catch {
        memoryOk = false;
      }

      if (vectorStore) {
        try {
          await vectorStore.query([], 1);
        } catch {
          vectorOk = false;
        }
      }

      return {
        status: memoryOk ? 'healthy' : 'degraded',
        memoryStore: memoryOk,
        vectorStore: vectorOk,
      };
    },

    /** Run consolidation */
    async consolidate(userId: string, consolidationConfig?: ConsolidationConfig): Promise<ConsolidationResult> {
      return consolidateMemories(userId, {
        memory: memoryStore,
        embeddings,
        vector: vectorStore,
      }, consolidationConfig);
    },

    /** Run pruning */
    async prune(userId: string, decayConfig?: DecayConfig): Promise<PruneResult> {
      return pruneMemories(userId, {
        memory: memoryStore,
        vector: vectorStore,
      }, decayConfig);
    },
  };
}
