/**
 * Agent Memory Tools
 *
 * Tools that the LLM can call during conversation to explicitly
 * manage persistent memory: remember, recall, update, forget.
 */

import type { Tool } from '../tools/types';
import type { WorkingMemoryManager, MemoryStore, VectorStore } from './types';

/**
 * Create memory tools for the agent to use during conversation.
 *
 * @param workingMemory - The working memory manager instance
 * @param stores - Optional direct store references for delete/update operations
 * @returns Array of Tool definitions
 */
export function createMemoryTools(
  workingMemory: WorkingMemoryManager,
  stores?: { memory: MemoryStore; vector?: VectorStore },
): Tool[] {
  return [
    {
      name: 'remember',
      description:
        'Store an important fact, preference, or instruction about the user for future conversations. Use this proactively when the user shares personal information, preferences, or important context.',
      parameters: {
        type: 'object',
        properties: {
          content: {
            type: 'string',
            description: 'The information to remember',
          },
          category: {
            type: 'string',
            enum: ['fact', 'preference', 'instruction', 'context'],
            description:
              'Category of memory: fact (personal info), preference (likes/dislikes), instruction (how-to), context (situational)',
          },
        },
        required: ['content'],
      },
      execute: async (args, ctx) => {
        const entry = await workingMemory.remember(
          ctx.userId,
          args.content as string,
          (args.category as 'fact' | 'preference' | 'instruction' | 'context') || undefined,
          ctx.conversationId,
        );
        return { success: true, id: entry.id, content: entry.content, category: entry.category };
      },
    },
    {
      name: 'recall',
      description:
        'Search your memories about the user. Use this to retrieve previously stored information before answering questions that might depend on user context.',
      parameters: {
        type: 'object',
        properties: {
          query: {
            type: 'string',
            description: 'Search query to find relevant memories',
          },
          limit: {
            type: 'number',
            description: 'Maximum number of memories to return (default: 10)',
          },
        },
        required: ['query'],
      },
      execute: async (args, ctx) => {
        const memories = await workingMemory.recall(
          ctx.userId,
          args.query as string,
          (args.limit as number) || 10,
        );
        return {
          success: true,
          count: memories.length,
          memories: memories.map((m) => ({
            id: m.id,
            content: m.content,
            category: m.category,
            confidence: m.confidence,
            createdAt: m.createdAt,
          })),
        };
      },
    },
    {
      name: 'update_memory',
      description:
        'Update an existing memory with corrected or updated information. Finds the closest matching memory and replaces it.',
      parameters: {
        type: 'object',
        properties: {
          query: {
            type: 'string',
            description: 'Search query to find the memory to update',
          },
          newContent: {
            type: 'string',
            description: 'The updated memory content',
          },
          category: {
            type: 'string',
            enum: ['fact', 'preference', 'instruction', 'context'],
            description: 'Updated category (optional)',
          },
        },
        required: ['query', 'newContent'],
      },
      execute: async (args, ctx) => {
        // Find the closest matching memory
        const matches = await workingMemory.recall(ctx.userId, args.query as string, 1);
        if (matches.length === 0) {
          // No existing memory found — create a new one
          const entry = await workingMemory.remember(
            ctx.userId,
            args.newContent as string,
            (args.category as 'fact' | 'preference' | 'instruction' | 'context') || undefined,
            ctx.conversationId,
          );
          return { success: true, action: 'created', id: entry.id, content: entry.content };
        }

        const old = matches[0];

        // Delete the old memory
        if (stores?.memory) {
          await stores.memory.delete(old.id);
        }
        if (stores?.vector) {
          try {
            await stores.vector.delete([old.id]);
          } catch {
            // Continue without vector deletion
          }
        }

        // Create the updated memory
        const entry = await workingMemory.remember(
          ctx.userId,
          args.newContent as string,
          (args.category as 'fact' | 'preference' | 'instruction' | 'context') || old.category,
          ctx.conversationId,
        );

        return {
          success: true,
          action: 'updated',
          oldId: old.id,
          newId: entry.id,
          oldContent: old.content,
          newContent: entry.content,
        };
      },
    },
    {
      name: 'forget',
      description:
        'Delete a specific memory. Use this when the user asks you to forget something or when information is no longer relevant.',
      parameters: {
        type: 'object',
        properties: {
          query: {
            type: 'string',
            description: 'Search query to find the memory to delete',
          },
        },
        required: ['query'],
      },
      execute: async (args, ctx) => {
        const matches = await workingMemory.recall(ctx.userId, args.query as string, 1);
        if (matches.length === 0) {
          return { success: false, message: 'No matching memory found' };
        }

        const target = matches[0];

        if (stores?.memory) {
          await stores.memory.delete(target.id);
        }
        if (stores?.vector) {
          try {
            await stores.vector.delete([target.id]);
          } catch {
            // Continue without vector deletion
          }
        }

        return { success: true, deletedId: target.id, deletedContent: target.content };
      },
    },
  ];
}
