/**
 * Tool Call Integrity
 *
 * Ensures tool call/result pairs are never orphaned when truncating
 * conversation history. Ported from stratus-workspace's proven algorithms.
 *
 * Rules enforced:
 * - Every assistant message with tool_calls MUST have ALL corresponding tool results
 * - No orphaned tool results (results without their parent assistant message)
 * - Recursive adjustment if initial fix creates new integrity issues
 */

import type { Message } from '../types';
import type { IntegrityResult } from './types';

/**
 * Validate and repair tool call integrity in a message array.
 *
 * After sliding window truncation, some messages may be orphaned:
 * - An assistant message with tool_calls but missing the corresponding tool results
 * - A tool result message whose parent assistant message was truncated
 *
 * This function adjusts the message array to fix these issues.
 */
export function validateToolCallIntegrity(messages: Message[]): IntegrityResult {
  const details: string[] = [];
  let adjustments = 0;
  let result = [...messages];

  // Iterate until stable (max 10 passes to prevent infinite loop)
  for (let pass = 0; pass < 10; pass++) {
    const { adjusted, changes } = fixIntegrityPass(result);

    if (changes === 0) break;

    result = adjusted;
    adjustments += changes;
    details.push(`Pass ${pass + 1}: ${changes} adjustment(s)`);
  }

  return {
    valid: adjustments === 0,
    messages: result,
    adjustments,
    details,
  };
}

/**
 * Single pass of integrity fixing.
 * Returns adjusted messages and number of changes made.
 */
function fixIntegrityPass(messages: Message[]): { adjusted: Message[]; changes: number } {
  let changes = 0;
  const toRemove = new Set<number>();

  // Build a map of tool call IDs to their assistant message index
  const toolCallOwners = new Map<string, number>();
  // Build a map of tool result call IDs to their message index
  const toolResultIndex = new Map<string, number>();

  for (let i = 0; i < messages.length; i++) {
    const msg = messages[i];

    if (msg.role === 'assistant' && msg.toolCalls) {
      for (const tc of msg.toolCalls) {
        if (tc.id) {
          toolCallOwners.set(tc.id, i);
        }
      }
    }

    if (msg.role === 'tool' && msg.toolCallId) {
      toolResultIndex.set(msg.toolCallId, i);
    }
  }

  // Check 1: Find assistant messages with tool calls that have missing results
  for (let i = 0; i < messages.length; i++) {
    const msg = messages[i];
    if (msg.role !== 'assistant' || !msg.toolCalls || msg.toolCalls.length === 0) continue;

    const allResultsPresent = msg.toolCalls.every(
      tc => tc.id && toolResultIndex.has(tc.id)
    );

    if (!allResultsPresent) {
      // Remove this assistant message AND any results that do exist for it
      toRemove.add(i);
      changes++;

      for (const tc of msg.toolCalls) {
        if (tc.id && toolResultIndex.has(tc.id)) {
          toRemove.add(toolResultIndex.get(tc.id)!);
        }
      }
    }
  }

  // Check 2: Find orphaned tool results (no parent assistant message)
  for (let i = 0; i < messages.length; i++) {
    const msg = messages[i];
    if (msg.role !== 'tool' || !msg.toolCallId) continue;

    if (!toolCallOwners.has(msg.toolCallId)) {
      toRemove.add(i);
      changes++;
    }
  }

  if (changes === 0) {
    return { adjusted: messages, changes: 0 };
  }

  // Filter out removed messages
  const adjusted = messages.filter((_, i) => !toRemove.has(i));
  return { adjusted, changes };
}

/**
 * Adjust a split index to maintain tool call integrity.
 *
 * When splitting messages into "old" and "recent" at a given index,
 * this adjusts the split point so that tool call/result pairs stay together.
 *
 * @param messages - Full message array
 * @param splitIndex - Initial split index (everything >= splitIndex is "recent")
 * @returns Adjusted split index
 */
export function adjustSplitForToolIntegrity(messages: Message[], splitIndex: number): number {
  if (splitIndex <= 0 || splitIndex >= messages.length) return splitIndex;

  let adjusted = splitIndex;

  // Look at messages around the split point
  for (let pass = 0; pass < 5; pass++) {
    let changed = false;

    // Check if the first "recent" message is a tool result without its parent
    for (let i = adjusted; i < messages.length; i++) {
      const msg = messages[i];
      if (msg.role !== 'tool' || !msg.toolCallId) break;

      // Find the parent assistant message
      let parentIndex = -1;
      for (let j = i - 1; j >= 0; j--) {
        if (messages[j].role === 'assistant' && messages[j].toolCalls) {
          const hasCall = messages[j].toolCalls!.some(tc => tc.id === msg.toolCallId);
          if (hasCall) {
            parentIndex = j;
            break;
          }
        }
      }

      if (parentIndex >= 0 && parentIndex < adjusted) {
        // Parent is in "old" section — move split back to include it
        adjusted = parentIndex;
        changed = true;
        break;
      }
    }

    // Check if the last "old" message is an assistant with tool calls that have results in "recent"
    if (adjusted > 0) {
      const lastOld = messages[adjusted - 1];
      if (lastOld.role === 'assistant' && lastOld.toolCalls) {
        const hasResultsInRecent = lastOld.toolCalls.some(tc => {
          for (let j = adjusted; j < messages.length; j++) {
            if (messages[j].role === 'tool' && messages[j].toolCallId === tc.id) {
              return true;
            }
          }
          return false;
        });

        if (hasResultsInRecent) {
          // Move split forward to keep the assistant message with its results
          adjusted = adjusted - 1;
          // Actually, we should include the assistant AND its results in recent
          // So find all tool results for this assistant
          changed = true;
        }
      }
    }

    if (!changed) break;
  }

  return Math.max(0, adjusted);
}
