/**
 * Memory Analytics
 *
 * Calculate statistics and insights about a user's memory store.
 */

import type { MemoryEntry } from './types';

export interface MemoryStats {
  /** Total number of active memories */
  total: number;
  /** Count by memory type */
  byType: Record<string, number>;
  /** Count by category */
  byCategory: Record<string, number>;
  /** Count by persistence level */
  byPersistence: Record<string, number>;
  /** Average confidence score */
  averageConfidence: number;
  /** Average age in days */
  averageAge: number;
  /** Number of memories expiring within 7 days */
  expiringSoon: number;
  /** Number of memories accessed in the last 7 days */
  recentlyAccessed: number;
  /** Count by source */
  bySource: Record<string, number>;
  /** Total superseded (version history) */
  superseded: number;
}

/**
 * Calculate comprehensive memory statistics.
 */
export function calculateMemoryStats(memories: MemoryEntry[]): MemoryStats {
  const now = Date.now();
  const WEEK = 7 * 24 * 60 * 60 * 1000;

  const active = memories.filter(m => !m.supersededBy);
  const superseded = memories.length - active.length;

  const byType: Record<string, number> = {};
  const byCategory: Record<string, number> = {};
  const byPersistence: Record<string, number> = {};
  const bySource: Record<string, number> = {};

  let totalConfidence = 0;
  let totalAge = 0;
  let expiringSoon = 0;
  let recentlyAccessed = 0;

  for (const mem of active) {
    // By type
    const type = mem.memoryType ?? 'unclassified';
    byType[type] = (byType[type] ?? 0) + 1;

    // By category
    byCategory[mem.category] = (byCategory[mem.category] ?? 0) + 1;

    // By persistence
    const persistence = mem.persistenceLevel ?? 'unclassified';
    byPersistence[persistence] = (byPersistence[persistence] ?? 0) + 1;

    // By source
    bySource[mem.source] = (bySource[mem.source] ?? 0) + 1;

    // Aggregates
    totalConfidence += mem.confidence;
    totalAge += now - mem.createdAt;

    // Expiring soon
    if (mem.expiresAt && mem.expiresAt - now < WEEK && mem.expiresAt > now) {
      expiringSoon++;
    }

    // Recently accessed
    if (now - mem.lastAccessedAt < WEEK) {
      recentlyAccessed++;
    }
  }

  const total = active.length;
  const avgAgeDays = total > 0 ? totalAge / total / (24 * 60 * 60 * 1000) : 0;

  return {
    total,
    byType,
    byCategory,
    byPersistence,
    averageConfidence: total > 0 ? totalConfidence / total : 0,
    averageAge: avgAgeDays,
    expiringSoon,
    recentlyAccessed,
    bySource,
    superseded,
  };
}
