/**
 * Context Manager
 *
 * Orchestrates the full context management pipeline:
 * 1. Calculate token budget
 * 2. Inject working memory into system prompt
 * 3. Apply sliding window with tool integrity
 * 4. Summarize truncated messages
 * 5. Return managed messages + enriched system prompt
 */

import type { Message } from '../types';
import type {
  ContextConfig,
  ContextResult,
  SummaryState,
  WorkingMemoryManager,
  Tokenizer,
} from './types';
import { estimateTokens, getTokenizer } from './token-counter';
import { getContextWindow } from './context-window';
import { applyWindow } from './sliding-window';
import { summarizeMessages } from './summarizer';

/**
 * Options for the context management pipeline
 */
export interface ManageContextOptions {
  /** Messages to manage */
  messages: Message[];
  /** Base system prompt */
  systemPrompt: string;
  /** User ID (for working memory) */
  userId: string;
  /** Context configuration */
  config: ContextConfig;
  /** Existing summary from previous truncation */
  existingSummary?: SummaryState;
}

/**
 * Run the full context management pipeline.
 *
 * This is the main entry point. Call it before each LLM request
 * to ensure messages fit within the context window while preserving
 * the most relevant context.
 *
 * @example
 * ```typescript
 * const result = await manageContext({
 *   messages,
 *   systemPrompt,
 *   userId: 'user-123',
 *   config: {
 *     model: 'gpt-4o',
 *     maxResponseTokens: 4096,
 *     summary: { provider: { apiKey: '...', baseUrl: '...' } },
 *     workingMemory: myWorkingMemoryManager,
 *   },
 *   existingSummary: previousSummary,
 * });
 *
 * // Use result.messages and result.systemPrompt for the LLM call
 * ```
 */
export async function manageContext(options: ManageContextOptions): Promise<ContextResult> {
  const { messages, systemPrompt, userId, config, existingSummary } = options;
  const tokenizer = config.tokenizer;
  const tok = getTokenizer(tokenizer);

  // Step 1: Get context window size
  const contextWindow = getContextWindow(config.model, {
    override: config.contextWindow,
  });

  // Step 2: Get working memory context
  let memoryContext = '';
  let memoryTokens = 0;

  if (config.workingMemory) {
    try {
      memoryContext = await config.workingMemory.getContextForPrompt(userId, messages);
      memoryTokens = memoryContext ? tok.count(memoryContext) : 0;
    } catch (err) {
      console.warn('[ContextManager] Working memory retrieval failed:', err);
    }
  }

  // Step 3: Calculate existing summary tokens
  const summaryTokens = existingSummary ? existingSummary.tokenCount : 0;

  // Step 4: Build enriched system prompt
  let enrichedPrompt = systemPrompt;
  if (memoryContext) {
    enrichedPrompt = `${memoryContext}\n\n${enrichedPrompt}`;
  }
  if (existingSummary) {
    enrichedPrompt = `## Previous Conversation Summary\n${existingSummary.text}\n\n${enrichedPrompt}`;
  }

  // Step 5: Apply sliding window
  const windowResult = applyWindow({
    messages,
    systemPrompt: enrichedPrompt,
    contextWindow,
    maxResponseTokens: config.maxResponseTokens,
    summaryTokens: 0, // Already included in enrichedPrompt
    memoryTokens: 0,   // Already included in enrichedPrompt
    tokenizer,
  });

  // Step 6: If truncation happened, summarize old messages
  let newSummary: SummaryState | undefined;

  if (windowResult.wasTruncated && windowResult.oldMessages.length > 0 && config.summary) {
    try {
      newSummary = await summarizeMessages(
        windowResult.oldMessages,
        existingSummary,
        config.summary,
      );

      // Update enriched prompt with new summary (replace old one if present)
      if (existingSummary) {
        enrichedPrompt = enrichedPrompt.replace(
          `## Previous Conversation Summary\n${existingSummary.text}`,
          `## Previous Conversation Summary\n${newSummary.text}`,
        );
      } else {
        // Insert summary before the base system prompt
        const baseIndex = enrichedPrompt.indexOf(systemPrompt);
        if (baseIndex > 0) {
          enrichedPrompt = enrichedPrompt.slice(0, baseIndex) +
            `## Previous Conversation Summary\n${newSummary.text}\n\n` +
            enrichedPrompt.slice(baseIndex);
        } else {
          enrichedPrompt = `## Previous Conversation Summary\n${newSummary.text}\n\n${enrichedPrompt}`;
        }
      }
    } catch (err) {
      console.warn('[ContextManager] Summarization failed:', err);
      // Continue without summary — the sliding window still works
    }
  }

  // Step 7: Calculate estimated total tokens
  const promptTokens = estimateTokens(enrichedPrompt, tokenizer);
  const estimatedTokens = promptTokens + windowResult.recentTokens;

  return {
    messages: windowResult.recentMessages,
    systemPrompt: enrichedPrompt,
    estimatedTokens,
    wasTruncated: windowResult.wasTruncated,
    newSummary,
    summarizedMessageCount: windowResult.oldMessages.length,
    budget: windowResult.budget,
  };
}
