/**
 * Active Forgetting & Decay Engine
 *
 * Implements exponential decay, confidence-based pruning,
 * expiration handling, and access reinforcement.
 */

import type {
  MemoryEntry,
  MemoryStore,
  VectorStore,
} from './types';

// ============================================
// Configuration
// ============================================

export interface DecayConfig {
  /** Half-life in days for confidence decay (default: 180) */
  halfLifeDays?: number;
  /** Minimum confidence before pruning (default: 0.3) */
  minConfidence?: number;
  /** Grace period after expiration before deletion, in hours (default: 24) */
  expirationGracePeriodHours?: number;
}

export interface PruneResult {
  /** Number of memories pruned (deleted) */
  pruned: number;
  /** Number of expired memories removed */
  expired: number;
  /** Details of pruning actions */
  details: string[];
}

// ============================================
// Decay Calculation
// ============================================

/**
 * Calculate the decay-adjusted score for a memory entry.
 * Uses exponential decay based on time since last access.
 *
 * Formula: score *= exp(-ageDays / (halfLife * 1.44))
 * The 1.44 factor converts half-life to the exponential decay constant.
 */
export function calculateDecayScore(entry: MemoryEntry, config?: DecayConfig): number {
  const halfLifeDays = config?.halfLifeDays ?? 180;
  const now = Date.now();
  const ageDays = (now - entry.lastAccessedAt) / (1000 * 60 * 60 * 24);

  // Exponential decay
  const decayFactor = Math.exp(-ageDays / (halfLifeDays * 1.44));

  // Base score is confidence
  let score = entry.confidence * decayFactor;

  // Persistence level adjustments
  if (entry.persistenceLevel === 'longTerm') {
    // Long-term memories decay much slower
    score = entry.confidence * Math.exp(-ageDays / (halfLifeDays * 4 * 1.44));
  } else if (entry.persistenceLevel === 'ephemeral') {
    // Ephemeral memories decay much faster
    score = entry.confidence * Math.exp(-ageDays / (halfLifeDays * 0.25 * 1.44));
  }

  // Access count provides some resistance to decay
  const accessBoost = Math.min(0.2, (entry.accessCount ?? 0) * 0.02);
  score += accessBoost;

  return Math.max(0, Math.min(1, score));
}

// ============================================
// Pruning
// ============================================

/**
 * Prune low-confidence and expired memories for a user.
 *
 * Rules:
 * - Never prune `longTerm` memories (unless expired)
 * - Prune `shortTerm` if confidence < minConfidence AND age > 90 days
 * - Aggressively prune `ephemeral` if confidence < 0.5 OR age > 30 days
 * - Always delete expired memories past grace period
 */
export async function pruneMemories(
  userId: string,
  stores: { memory: MemoryStore; vector?: VectorStore },
  config?: DecayConfig,
): Promise<PruneResult> {
  const minConfidence = config?.minConfidence ?? 0.3;
  const now = Date.now();
  const DAY = 24 * 60 * 60 * 1000;

  const result: PruneResult = { pruned: 0, expired: 0, details: [] };
  const toDelete: string[] = [];

  const allMemories = await stores.memory.listByUser(userId);

  for (const mem of allMemories) {
    // Skip already superseded
    if (mem.supersededBy) continue;

    const decayScore = calculateDecayScore(mem, config);
    const ageDays = (now - mem.lastAccessedAt) / DAY;

    let shouldPrune = false;
    let reason = '';

    // Check expiration first
    if (mem.expiresAt) {
      const graceMs = (config?.expirationGracePeriodHours ?? 24) * 60 * 60 * 1000;
      if (now > mem.expiresAt + graceMs) {
        shouldPrune = true;
        reason = 'expired';
        result.expired++;
      }
    }

    if (!shouldPrune) {
      switch (mem.persistenceLevel) {
        case 'longTerm':
          // Never auto-prune longTerm (only expires)
          break;

        case 'shortTerm':
          if (decayScore < minConfidence && ageDays > 90) {
            shouldPrune = true;
            reason = `shortTerm decay (score=${decayScore.toFixed(2)}, age=${ageDays.toFixed(0)}d)`;
          }
          break;

        case 'ephemeral':
          if (decayScore < 0.5 || ageDays > 30) {
            shouldPrune = true;
            reason = `ephemeral decay (score=${decayScore.toFixed(2)}, age=${ageDays.toFixed(0)}d)`;
          }
          break;

        default:
          // Unclassified memories: use general threshold
          if (decayScore < minConfidence && ageDays > 90) {
            shouldPrune = true;
            reason = `unclassified decay (score=${decayScore.toFixed(2)}, age=${ageDays.toFixed(0)}d)`;
          }
          break;
      }
    }

    if (shouldPrune) {
      toDelete.push(mem.id);
      result.details.push(`Pruned "${mem.content.slice(0, 40)}..." — ${reason}`);
    }
  }

  // Delete from stores
  for (const id of toDelete) {
    await stores.memory.delete(id);
  }

  if (stores.vector && toDelete.length > 0) {
    try {
      await stores.vector.delete(toDelete);
    } catch {
      // Continue without vector deletion
    }
  }

  result.pruned = toDelete.length;
  return result;
}

// ============================================
// Expiration Check
// ============================================

/**
 * Check and remove expired memories.
 * Returns the number of memories removed.
 */
export async function checkExpirations(
  userId: string,
  stores: { memory: MemoryStore; vector?: VectorStore },
  config?: DecayConfig,
): Promise<number> {
  const graceMs = (config?.expirationGracePeriodHours ?? 24) * 60 * 60 * 1000;
  const now = Date.now();

  const allMemories = await stores.memory.listByUser(userId);
  const expired = allMemories.filter(
    m => m.expiresAt && now > m.expiresAt + graceMs && !m.supersededBy
  );

  for (const mem of expired) {
    await stores.memory.delete(mem.id);
  }

  if (stores.vector && expired.length > 0) {
    try {
      await stores.vector.delete(expired.map(m => m.id));
    } catch {
      // Continue
    }
  }

  return expired.length;
}
