/**
 * Knowledge Graph
 *
 * Build and query an entity-relation graph from memories.
 * Enables multi-hop reasoning: "What does the user know about X?"
 */

import type { MemoryEntry } from './types';
import { classifyEntity } from './entities';

// ============================================
// Types
// ============================================

export interface KnowledgeNode {
  /** Unique node ID (derived from entity text) */
  id: string;
  /** Display label */
  label: string;
  /** Entity type */
  type: string;
  /** Memory IDs that reference this entity */
  memoryIds: string[];
}

export interface KnowledgeEdge {
  /** Source node ID */
  source: string;
  /** Target node ID */
  target: string;
  /** Relationship type */
  relation: string;
  /** Edge weight (number of shared memories) */
  weight: number;
}

export interface KnowledgeGraph {
  nodes: KnowledgeNode[];
  edges: KnowledgeEdge[];
}

// ============================================
// Graph Building
// ============================================

/**
 * Build a knowledge graph from memory entries.
 *
 * Nodes are entities extracted from memories.
 * Edges connect entities that co-occur in the same memory.
 */
export function buildKnowledgeGraph(memories: MemoryEntry[]): KnowledgeGraph {
  const nodeMap = new Map<string, KnowledgeNode>();
  const edgeMap = new Map<string, KnowledgeEdge>();

  for (const mem of memories) {
    if (mem.supersededBy) continue;
    const entities = mem.entities ?? [];
    if (entities.length === 0) continue;

    // Create/update nodes
    for (const entity of entities) {
      const nodeId = entityToId(entity);
      const existing = nodeMap.get(nodeId);
      if (existing) {
        if (!existing.memoryIds.includes(mem.id)) {
          existing.memoryIds.push(mem.id);
        }
      } else {
        nodeMap.set(nodeId, {
          id: nodeId,
          label: entity,
          type: classifyEntity(entity),
          memoryIds: [mem.id],
        });
      }
    }

    // Create edges for co-occurring entities
    for (let i = 0; i < entities.length; i++) {
      for (let j = i + 1; j < entities.length; j++) {
        const sourceId = entityToId(entities[i]);
        const targetId = entityToId(entities[j]);
        const edgeKey = [sourceId, targetId].sort().join('::');

        const existing = edgeMap.get(edgeKey);
        if (existing) {
          existing.weight++;
        } else {
          edgeMap.set(edgeKey, {
            source: sourceId,
            target: targetId,
            relation: 'co-occurs',
            weight: 1,
          });
        }
      }
    }

    // Add explicit relations from memory
    if (mem.relations) {
      for (const rel of mem.relations) {
        const sourceId = mem.entities?.[0] ? entityToId(mem.entities[0]) : mem.id;
        const targetId = rel.targetId;
        const edgeKey = `${sourceId}::${targetId}::${rel.type}`;

        if (!edgeMap.has(edgeKey)) {
          edgeMap.set(edgeKey, {
            source: sourceId,
            target: targetId,
            relation: rel.type,
            weight: 1,
          });
        }
      }
    }
  }

  return {
    nodes: Array.from(nodeMap.values()),
    edges: Array.from(edgeMap.values()),
  };
}

/**
 * Query the knowledge graph starting from an entity.
 * Returns nodes reachable within `hops` edges.
 */
export function queryGraph(
  graph: KnowledgeGraph,
  entity: string,
  hops: number = 2,
): KnowledgeNode[] {
  const startId = entityToId(entity);
  const startNode = graph.nodes.find(n => n.id === startId);
  if (!startNode) return [];

  const visited = new Set<string>();
  const result: KnowledgeNode[] = [];
  let frontier = [startId];

  for (let depth = 0; depth <= hops; depth++) {
    const nextFrontier: string[] = [];

    for (const nodeId of frontier) {
      if (visited.has(nodeId)) continue;
      visited.add(nodeId);

      const node = graph.nodes.find(n => n.id === nodeId);
      if (node) result.push(node);

      // Find neighbors
      for (const edge of graph.edges) {
        if (edge.source === nodeId && !visited.has(edge.target)) {
          nextFrontier.push(edge.target);
        }
        if (edge.target === nodeId && !visited.has(edge.source)) {
          nextFrontier.push(edge.source);
        }
      }
    }

    frontier = nextFrontier;
  }

  return result;
}

// ============================================
// Helpers
// ============================================

function entityToId(entity: string): string {
  return entity.toLowerCase().replace(/\s+/g, '_').replace(/[^a-z0-9_]/g, '');
}
