/**
 * Qdrant Vector Store Adapter
 *
 * Connects SAGE working memory to Qdrant for production-grade
 * semantic similarity search. Uses Qdrant's REST API (no SDK dependency).
 *
 * @example
 * ```typescript
 * const vectorStore = new QdrantVectorStore({
 *   url: 'http://localhost:6333',
 *   collectionName: 'sage_memories',
 * });
 * ```
 */

import type { VectorStore } from '../types';

/**
 * Qdrant configuration
 */
export interface QdrantConfig {
  /** Qdrant server URL (e.g., 'http://localhost:6333') */
  url: string;
  /** API key for Qdrant Cloud (optional for local) */
  apiKey?: string;
  /** Collection name to use */
  collectionName: string;
  /** Vector dimensions (auto-detected from first upsert if not set) */
  dimensions?: number;
  /** Distance metric (default: 'Cosine') */
  distance?: 'Cosine' | 'Euclid' | 'Dot';
  /** Request timeout in ms (default: 10000) */
  timeout?: number;
}

/**
 * Qdrant vector store implementation.
 * Uses REST API directly — no @qdrant/js-client-rest dependency needed.
 */
export class QdrantVectorStore implements VectorStore {
  private config: Required<Omit<QdrantConfig, 'apiKey' | 'dimensions'>> & {
    apiKey?: string;
    dimensions?: number;
  };
  private collectionInitialized = false;

  constructor(config: QdrantConfig) {
    this.config = {
      url: config.url.replace(/\/$/, ''), // Remove trailing slash
      apiKey: config.apiKey,
      collectionName: config.collectionName,
      dimensions: config.dimensions,
      distance: config.distance ?? 'Cosine',
      timeout: config.timeout ?? 10_000,
    };
  }

  /**
   * Ensure the collection exists, creating it if necessary
   */
  private async ensureCollection(dimensions: number): Promise<void> {
    if (this.collectionInitialized) return;

    const { url, collectionName, distance } = this.config;

    // Check if collection exists
    try {
      const checkRes = await this.fetch(`${url}/collections/${collectionName}`);
      if (checkRes.ok) {
        this.collectionInitialized = true;
        return;
      }
    } catch {
      // Collection doesn't exist, create it
    }

    // Create collection
    const createRes = await this.fetch(`${url}/collections/${collectionName}`, {
      method: 'PUT',
      body: JSON.stringify({
        vectors: {
          size: dimensions,
          distance,
        },
      }),
    });

    if (!createRes.ok) {
      const error = await createRes.text();
      throw new Error(`Failed to create Qdrant collection: ${createRes.status} - ${error}`);
    }

    this.collectionInitialized = true;
  }

  async upsert(entries: Array<{
    id: string;
    vector: number[];
    metadata: Record<string, unknown>;
  }>): Promise<void> {
    if (entries.length === 0) return;

    // Auto-detect dimensions from first entry
    const dimensions = this.config.dimensions ?? entries[0].vector.length;
    await this.ensureCollection(dimensions);

    const { url, collectionName } = this.config;

    const points = entries.map(entry => ({
      id: stringToUUID(entry.id),
      vector: entry.vector,
      payload: {
        ...entry.metadata,
        _sage_id: entry.id, // Preserve original string ID
      },
    }));

    const res = await this.fetch(`${url}/collections/${collectionName}/points`, {
      method: 'PUT',
      body: JSON.stringify({
        points,
        wait: true,
      }),
    });

    if (!res.ok) {
      const error = await res.text();
      throw new Error(`Qdrant upsert failed: ${res.status} - ${error}`);
    }
  }

  async query(
    vector: number[],
    topK: number,
    filter?: Record<string, unknown>,
  ): Promise<Array<{ id: string; score: number; metadata?: Record<string, unknown> }>> {
    const dimensions = this.config.dimensions ?? vector.length;
    await this.ensureCollection(dimensions);

    const { url, collectionName } = this.config;

    const body: Record<string, unknown> = {
      vector,
      limit: topK,
      with_payload: true,
    };

    // Convert simple filter to Qdrant filter format
    if (filter && Object.keys(filter).length > 0) {
      body.filter = {
        must: Object.entries(filter).map(([key, value]) => ({
          key,
          match: { value },
        })),
      };
    }

    const res = await this.fetch(`${url}/collections/${collectionName}/points/search`, {
      method: 'POST',
      body: JSON.stringify(body),
    });

    if (!res.ok) {
      const error = await res.text();
      throw new Error(`Qdrant search failed: ${res.status} - ${error}`);
    }

    const data = await res.json() as {
      result?: Array<{
        id: string | number;
        score: number;
        payload?: Record<string, unknown>;
      }>;
    };

    return (data.result || []).map(point => ({
      id: (point.payload?._sage_id as string) || String(point.id),
      score: point.score,
      metadata: point.payload,
    }));
  }

  async delete(ids: string[]): Promise<void> {
    if (ids.length === 0) return;

    const { url, collectionName } = this.config;

    const res = await this.fetch(`${url}/collections/${collectionName}/points/delete`, {
      method: 'POST',
      body: JSON.stringify({
        points: ids.map(id => stringToUUID(id)),
        wait: true,
      }),
    });

    if (!res.ok) {
      const error = await res.text();
      throw new Error(`Qdrant delete failed: ${res.status} - ${error}`);
    }
  }

  /**
   * Internal fetch with auth headers and timeout
   */
  private fetch(url: string, init?: RequestInit): Promise<Response> {
    const headers: Record<string, string> = {
      'Content-Type': 'application/json',
    };

    if (this.config.apiKey) {
      headers['api-key'] = this.config.apiKey;
    }

    return fetch(url, {
      ...init,
      headers: {
        ...headers,
        ...(init?.headers as Record<string, string>),
      },
      signal: AbortSignal.timeout(this.config.timeout),
    });
  }
}

/**
 * Convert a string ID to a UUID-like format for Qdrant.
 * Qdrant requires UUIDs or unsigned integers as point IDs.
 * This creates a deterministic UUID from any string.
 */
function stringToUUID(str: string): string {
  // Simple hash-based UUID generation
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    const char = str.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash = hash & hash; // Convert to 32bit integer
  }

  // Generate a deterministic UUID v4-like format
  const hex = Math.abs(hash).toString(16).padStart(8, '0');
  const hex2 = simpleHash(str + '_2').toString(16).padStart(8, '0');
  const hex3 = simpleHash(str + '_3').toString(16).padStart(4, '0');
  const hex4 = simpleHash(str + '_4').toString(16).padStart(4, '0');
  const hex5 = simpleHash(str + '_5').toString(16).padStart(12, '0');

  return `${hex.slice(0, 8)}-${hex2.slice(0, 4)}-4${hex3.slice(0, 3)}-${hex4.slice(0, 4)}-${hex5.slice(0, 12)}`;
}

function simpleHash(str: string): number {
  let hash = 5381;
  for (let i = 0; i < str.length; i++) {
    hash = ((hash << 5) + hash) + str.charCodeAt(i);
    hash = hash & 0x7fffffff;
  }
  return hash;
}
